import unittest

from inventory.models import Item
from tests.helpers import store_with


class HiddenFind(unittest.TestCase):
    def setUp(self):
        self.s = store_with(
            Item("C", "c", 1, 1, ["Metal", "sale"]),
            Item("A", "a", 1, 1, ["metal"]),
            Item("B", "b", 1, 1, ["plastic", "SALE"]),
        )

    def skus(self, items):
        return [i.sku for i in items]

    def test_all(self):
        self.assertEqual(self.skus(self.s.find(["metal", "Sale"])), ["C"])
        self.assertEqual(self.skus(self.s.find(["METAL"], "all")), ["A", "C"])

    def test_any(self):
        self.assertEqual(self.skus(self.s.find(["sale", "metal"], "any")), ["A", "B", "C"])
        self.assertEqual(self.skus(self.s.find(["plastic"], "any")), ["B"])

    def test_edges(self):
        self.assertEqual(self.skus(self.s.find([])), ["A", "B", "C"])
        with self.assertRaises(ValueError):
            self.s.find(["metal"], "none")

import io
import unittest
from contextlib import redirect_stdout

from inventory import cli
from inventory.pricing import split_total


class HiddenSplit(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(split_total(100, [1, 1, 1]), [34, 33, 33])
        self.assertEqual(split_total(1000, [50, 30, 20]), [500, 300, 200])
        self.assertEqual(split_total(101, [1, 2]), [34, 67])
        self.assertEqual(split_total(5, [0, 1]), [0, 5])
        self.assertEqual(split_total(7, [3, 3, 1]), [3, 3, 1])
        self.assertEqual(split_total(10, [1, 1, 1, 1, 1, 1]), [2, 2, 2, 2, 1, 1])

    def test_sums(self):
        for total in (0, 1, 99, 12345):
            for w in ([1], [1, 1, 1], [7, 0, 3], [5, 5, 5, 5, 1]):
                self.assertEqual(sum(split_total(total, w)), total)

    def test_errors(self):
        for total, w in ((10, []), (10, [1, -1]), (10, [0, 0]), (-1, [1])):
            with self.assertRaises(ValueError):
                split_total(total, w)

    def test_cli(self):
        buf = io.StringIO()
        with redirect_stdout(buf):
            self.assertEqual(cli.main(["split", "1000", "1", "2"]), 0)
        self.assertEqual(buf.getvalue().split(), ["3.33", "6.67"])
